from .record import Migration

class CircularDependencyError(Exception):
    pass

class MissingDependencyError(Exception):
    pass

class MigrationGraph:
    def __init__(self):
        self._migrations: dict[str, Migration] = {}

    def add_migration(self, migration: Migration) -> None:
        self._migrations[migration.name] = migration

    def topological_sort(self) -> list[str]:
        indeg = {k: 0 for k in self._migrations}
        adj: dict[str, list[str]] = {k: [] for k in self._migrations}
        for name, m in self._migrations.items():
            for dep in m.dependencies:
                if dep not in self._migrations:
                    raise MissingDependencyError(f"Missing dependency {dep}")
                adj[dep].append(name)
                indeg[name] += 1
        queue = [k for k, v in indeg.items() if v == 0]
        queue.sort()
        res = []
        while queue:
            curr = queue.pop(0)
            res.append(curr)
            for nxt in sorted(adj[curr]):
                indeg[nxt] -= 1
                if indeg[nxt] == 0:
                    queue.append(nxt)
        if len(res) != len(self._migrations):
            raise CircularDependencyError("Cycle detected")
        return res
