from typing import Any
from .record import Migration, MigrationState
from .graph import MigrationGraph

class TamperedMigrationError(Exception):
    pass

class MigrationEngine:
    def __init__(self, graph: MigrationGraph, state: MigrationState):
        self.graph = graph
        self.state = state
        self.context: dict[str, Any] = {}

    def upgrade(self, target: str | None = None) -> list[str]:
        for name, applied_chk in self.state.applied_migrations.items():
            if name in self.graph._migrations:
                if self.graph._migrations[name].checksum != applied_chk:
                    raise TamperedMigrationError(f"Tampered migration {name}")

        order = self.graph.topological_sort()
        applied = []
        for name in order:
            if name not in self.state.applied_migrations:
                m = self.graph._migrations[name]
                m.up(self.context)
                self.state.applied_migrations[name] = m.checksum
                applied.append(name)
            if target is not None and name == target:
                break
        return applied

    def downgrade(self, target: str) -> list[str]:
        order = self.graph.topological_sort()
        if target not in order:
            raise ValueError(f"Target {target} not in graph")
        target_idx = order.index(target)
        to_revert = [name for name in reversed(order[target_idx + 1:]) if name in self.state.applied_migrations]
        reverted = []
        for name in to_revert:
            m = self.graph._migrations[name]
            m.down(self.context)
            del self.state.applied_migrations[name]
            reverted.append(name)
        return reverted
